+/// True if `addr` is only reachable from inside a LAN: the RFC 1918 IPv4 blocks,
+/// IPv4/IPv6 loopback, or an IPv6 unique-local address (fc00::/7).
+fn is_lan_only_address(addr: &PeerAddress) -> bool {
+    match addr.to_ipaddr() {
+        IpAddr::V4(v4) => {
+            let [a, b, _, _] = v4.octets();
+            match a {
+                10 | 127 => true,
+                172 => (16..=31).contains(&b),
+                192 => b == 168,
+                _ => false,
+            }
+        }
+        IpAddr::V6(v6) => v6.is_loopback() || (v6.segments()[0] & 0xfe00) == 0xfc00,
+    }
+}
